(()=>{
'use strict';
const app=document.getElementById('app'),dialog=document.getElementById('detail-dialog'),data=window.FITTINGS,picker=document.getElementById('picker-dialog');
const titles=['','Supply connections at equipment','Supply trunk branch takeoffs','Reducing trunk takeoffs','Supply boots and stack heads','Return connections at equipment','Return trunk branches and boots','Panned joists and stud returns','Elbows and offsets','Supply trunk junctions','Return trunk junctions','Flexible duct junctions and bends','Transitions and oval squeezes'];
const variants={gallery:{n:1,name:'Gallery + detail dialog',desc:'Browse a wall of large drawings. Open one in a spacious dialog to configure and add it.',trade:'Most room for browsing; configuration temporarily covers the catalog.'},guided:{n:2,name:'Guided selection',desc:'Choose a group, then add a fitting from its drawing. Enter any required dimensions directly on the card.',trade:'Two steps; quantity is adjusted in the path list.'},focus:{n:3,name:'Drawing workbench',desc:'Inspect one large fitting at a time. Move through a thumbnail strip while its inputs stay beside it.',trade:'Best space for inspecting geometry; fewer fittings visible at once.'},compare:{n:4,name:'Compare before choosing',desc:'Pick two drawings, compare their geometry and required inputs, then add the fitting that matches.',trade:'Helps distinguish similar fittings; adds a comparison step.'},inline:{n:5,name:'Expandable visual catalog',desc:'Scan large illustrated rows. Expand a fitting’s inputs directly below its drawing.',trade:'Keeps the browsing context visible; a longer page to scan.'}};
const allowed={supply:[1,2,3,4,8,9,11,12],return:[5,6,7,8,10,11,12]},paths={supply:[],return:[]},straight={supply:35,return:25};
let variant='guided',type='supply',group=4,selected='4A',stage='groups',editing=-1,compare=[],compareOpen=false,expanded=null;
const drafts={};
const usuallyOnce=new Set([1,2,3,5,6]);
const favoriteKey='swift-duct-calc.fitting-picker.favorites.v1';
let favoritesOnly=false,storageAvailable=true;
let favoriteLayout='first';
function readFavorites(){try{const saved=JSON.parse(localStorage.getItem(favoriteKey)||'[]');return new Set((Array.isArray(saved)?saved:[]).filter(id=>data.some(f=>f.id===id)));}catch{return new Set();}}
let favorites=readFavorites();
const favoriteCount=g=>data.filter(f=>f.group===g&&favorites.has(f.id)).length;
function favoriteButton(id){const saved=favorites.has(id);return `<button class="favorite-button" data-action="favorite" data-id="${id}" aria-pressed="${saved}" aria-label="${saved?'Remove':'Add'} ${id} ${saved?'from':'to'} favorites"><span aria-hidden="true">${saved?'★':'☆'}</span> ${saved?'Favorited':'Favorite'}</button>`;}
function favoriteFilters(){if(favoriteLayout==='first')return `<small>★ ${favoriteCount(group)} favorites shown first</small>`;return `<div class="favorite-filters" role="group" aria-label="Fittings shown in this group"><button data-action="show-all" aria-pressed="${!favoritesOnly}">All fittings (${data.filter(f=>f.group===group).length})</button><button data-action="show-favorites" aria-pressed="${favoritesOnly}">★ Favorites (${favoriteCount(group)})</button></div>`;}
function syncFavoriteButtons(){document.querySelectorAll('[data-action="favorite"]').forEach(b=>{const id=b.dataset.id,saved=favorites.has(id);b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',`${saved?'Remove':'Add'} ${id} ${saved?'from':'to'} favorites`);b.innerHTML=`<span aria-hidden="true">${saved?'★':'☆'}</span> ${saved?'Favorited':'Favorite'}`;});}
function toggleFavorite(id){if(favorites.has(id))favorites.delete(id);else favorites.add(id);try{localStorage.setItem(favoriteKey,JSON.stringify([...favorites]));storageAvailable=true;}catch{storageAvailable=false;}renderBrowser();syncFavoriteButtons();const message=`${id} ${favorites.has(id)?'saved to':'removed from'} favorites.${storageAvailable?'':' Browser storage is unavailable; favorites last for this page only.'}`;status(message);if(dialog.open)dialog.querySelector('.favorite-status').textContent=message;}

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const find=id=>data.find(f=>f.id===id),items=()=>{const list=data.filter(f=>f.group===group&&(favoriteLayout==='first'||!favoritesOnly||favorites.has(f.id)));return favoriteLayout==='first'?[...list.filter(f=>favorites.has(f.id)),...list.filter(f=>!favorites.has(f.id))]:list;},fmt=n=>Number(n.toFixed(2)).toString();
function groupDivider(list,i){if(favoriteLayout!=='first'||!list.some(f=>favorites.has(f.id)))return '';if(i===0)return '<div class="favorite-section-label" role="heading" aria-level="3">★ Favorites</div>';if(!favorites.has(list[i].id)&&favorites.has(list[i-1].id))return '<div class="favorite-section-divider" role="separator" aria-label="End favorites. Other fittings">End favorites · Other fittings</div>';return '';}
const draft=id=>drafts[id]||(drafts[id]={h:'',w:'',branches:'',quantity:'1'});
function calculate(f,d){if(f.fixed!==undefined)return {value:f.fixed,note:'Prescribed reference value'};if(f.ratios){const h=Number(d.h),w=Number(d.w);if(!(h>0&&w>0&&Number.isFinite(h)&&Number.isFinite(w)))return {value:null,note:'Enter height and width to determine H/W.'};const r=h/w,row=f.ratios.find(x=>Math.abs(x.ratio-r)<1e-9);return row?{value:row.feet,note:`H/W = ${fmt(r)} · ${fmt(h)} × ${fmt(w)} in`}:{value:null,note:`H/W = ${fmt(r)}. Between-entry rules are not verified in this prototype. Try 10 × 20 or 20 × 20 in.`};}if(d.branches==='')return {value:null,note:'Select the downstream branch count.'};return {value:f.branches[Number(d.branches)].feet,note:`${d.branches==='5'?'5+':d.branches} downstream branches`};}
function art(f,cls='art'){return `<img class="${cls}" src="${esc(f.image)}" alt="${esc(f.id+' — '+f.name)}">`;}
function groupEntries(g){return paths[type].map((entry,index)=>({entry,index})).filter(({entry})=>find(entry.id).group===g);}
function groupQuantity(g){return groupEntries(g).reduce((sum,{entry})=>sum+entry.quantity,0);}
function repetitionWarning(id,quantity){const g=find(id).group;if(!usuallyOnce.has(g)||!Number.isSafeInteger(quantity)||quantity<1)return '';const existing=groupEntries(g).filter(({index})=>index!==editing).reduce((sum,{entry})=>sum+entry.quantity,0);if(existing+quantity<=1)return '';return `Group ${g} is generally used once per path. ${existing?`${existing} already added; this ${editing>=0?'edit':'entry'} brings the group to ${existing+quantity} fittings.`:`This entry has a quantity of ${quantity}.`} You can continue if this is intentional.`;}
function groupOverview(g){const entries=groupEntries(g),quantity=groupQuantity(g),f=entries.length?find(entries[0].entry.id):data.find(f=>f.group===g);return `<div class="group-option ${quantity?'has-fitting':''}" data-overview-group="${g}"><button class="group-card" data-action="group-card" data-group="${g}">${f?art(f,''):'<div class="empty">No sample drawings</div>'}<span>${titles[g]}<small>Group ${g}${f?'':' · Navigation only'}</small>${usuallyOnce.has(g)?'<small>Generally once per path</small>':''}</span></button><div class="group-path-state ${usuallyOnce.has(g)&&quantity>1?'repeated-group':''}">${quantity?`<strong>✓ ${quantity} fitting${quantity===1?'':'s'} added</strong>${entries.map(({entry,index})=>`<div class="group-added-fitting">${art(find(entry.id),'')}<span>${entry.id} × ${entry.quantity}</span><button data-action="edit" data-index="${index}" aria-label="Edit ${entry.id} in this path">Edit</button></div>`).join('')}${usuallyOnce.has(g)&&quantity>1?'<small>More than the usual one fitting</small>':''}`:'<small>No fitting added</small>'}</div><button class="group-favorites" data-action="group-favorites" data-group="${g}">★ Favorites (${favoriteCount(g)})</button></div>`;}
function groupUsage(g){const quantity=groupQuantity(g);if(!quantity)return '';return `<div class="group-usage"><strong>${quantity} fitting${quantity===1?'':'s'} from Group ${g} already in this path</strong><span>${groupEntries(g).map(({entry})=>`${entry.id} × ${entry.quantity}`).join(' · ')}</span>${usuallyOnce.has(g)?'<small>This group is generally used once per path. Additional fittings are allowed.</small>':''}</div>`;}
function groupSelect(){return `<label>Fitting group <select id="group">${allowed[type].map(g=>`<option value="${g}" ${group===g?'selected':''}>${titles[g]} · Group ${g}${groupQuantity(g)?` · ${groupQuantity(g)} added`:''}${favoriteCount(g)?` · ★ ${favoriteCount(g)}`:''}</option>`).join('')}</select></label>`;}
function card(f,action='choose'){const picked=compare.includes(f.id);return `<article class="art-card ${variant==='compare'&&picked?'selected':''}"><button class="art-button" data-action="${action}" data-id="${f.id}" aria-label="${action==='toggle'?'Compare':'Configure'} ${f.id}" ${action==='toggle'?`aria-pressed="${picked}"`:''}>${art(f)}</button><div class="caption"><div class="favorite-heading"><span class="code">${f.id}</span>${favoriteButton(f.id)}</div><h3>${esc(f.name)}</h3><p><small>${f.fixed!==undefined?`${f.fixed} ft per fitting`:f.ratios?'Determined from height and width':'Determined from downstream branches'}</small></p><button data-action="${action}" data-id="${f.id}">${action==='toggle'?(picked?'✓ Selected for comparison':'Compare this fitting'):'Choose fitting'}</button></div></article>`;}
function guidedCard(f){
 if(f.fixed!==undefined){const warning=repetitionWarning(f.id,1);return `<article class="art-card"><button class="art-button" data-action="choose" data-id="${f.id}" aria-label="Add ${f.id} to path">${art(f)}</button><div class="caption"><div class="favorite-heading"><span class="code">${f.id}</span>${favoriteButton(f.id)}</div><h3>${esc(f.name)}</h3><p>${f.fixed} ft per fitting</p>${warning?`<div class="repetition-warning">${esc(warning)}</div>`:''}<button class="primary" data-action="choose" data-id="${f.id}">${warning?'Add anyway':'Add fitting'}</button></div></article>`;}
 const d=draft(f.id);return `<article class="art-card guided-input-card" data-config="${f.id}" aria-label="Select ${f.id}">${art(f)}<div class="caption"><div class="favorite-heading"><span class="code">${f.id}</span>${favoriteButton(f.id)}</div><h3>${esc(f.name)}</h3>${f.ratios?`<div class="fields"><label>Height H (in)<input data-field="h" type="number" min="0.01" step="any" value="${esc(d.h)}" placeholder="10"></label><label>Width W (in)<input data-field="w" type="number" min="0.01" step="any" value="${esc(d.w)}" placeholder="20"></label></div>`:`<label>Downstream branches<select data-field="branches"><option value="">Choose count</option>${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${d.branches===String(n)?'selected':''}>${n===5?'5 or more':n}</option>`).join('')}</select></label><small>Count to the next reducer or trunk end.</small>`}<div class="result" aria-live="polite"><small>Equivalent length per fitting</small><output>—</output><small class="reason"></small></div><small class="subtotal"></small><div class="repetition-warning" role="status" hidden></div><button class="primary" data-action="add" data-id="${f.id}">Add fitting</button><details><summary>Reference & conditions</summary><p>Manual D · printed page ${esc(f.page)}<br>900 FPM · 0.08 IWC / 100 ft</p>${f.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</details></div></article>`;
}
function config(f){const d=draft(f.id),c=calculate(f,d);return `<section class="config" data-config="${f.id}" aria-label="Configure ${f.id}">${art(f,'hero-art')}<div class="config-controls"><div class="favorite-heading"><span class="code">${f.id}</span>${favoriteButton(f.id)}</div><h2>${esc(f.name)}</h2>${f.ratios?`<div class="fields"><label>Height H (in)<input data-field="h" type="number" min="0.01" step="any" value="${esc(d.h)}" placeholder="10"></label><label>Width W (in)<input data-field="w" type="number" min="0.01" step="any" value="${esc(d.w)}" placeholder="20"></label></div><small>Use the dimensions marked H and W in the drawing.</small>`:f.branches?`<label>Downstream branches<select data-field="branches"><option value="">Choose count</option>${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${d.branches===String(n)?'selected':''}>${n===5?'5 or more':n}</option>`).join('')}</select></label><small>Count to the next reducer or trunk end.</small>`:''}<div class="result" aria-live="polite"><small>Equivalent length per fitting</small><output>${c.value===null?'—':c.value+' ft'}</output><small class="reason">${esc(c.note)}</small></div>${variant==='guided'?'':`<label>Quantity<input data-field="quantity" type="number" min="1" step="1" value="${esc(d.quantity)}"></label>`}<small class="subtotal"></small><div class="repetition-warning" role="status" hidden></div><details><summary>Reference & fitting conditions</summary><p>Manual D · printed page ${esc(f.page)}<br>Reference: 900 FPM · 0.08 IWC / 100 ft</p>${f.notes.map(n=>`<p>${esc(n)}</p>`).join('')}${f.ratios?'<p>H/W 0.5 → 120 ft · H/W 1 → 85 ft</p>':''}</details><div class="actions"><button class="primary" data-action="add" data-id="${f.id}">${editing>=0?'Save fitting':'Add to path'}</button>${editing>=0?'<button data-action="cancel-edit">Cancel edit</button>':''}</div></div></section>`;}
function home(){app.innerHTML=`<div class="home"><div class="intro"><span class="step-label">Fitting picker · Design exploration</span><h1>Five ways to find the right fitting</h1><p>Each direction uses the same sample fittings and calculation inputs. The drawings lead; equivalent length stays read-only.</p><p>Try boots in Group 4, dimensions with 1F, and branch counts with 2A. Path entries are temporary and reset when you leave a direction. Star common fittings and compare two arrangements: favorites at the top of the group, or a separate Favorites tab. Use the Favorites layout selector in any preview. Your favorites are shared across all five previews and saved in this browser.</p></div><div class="directions">${Object.entries(variants).map(([key,v])=>`<a class="direction" href="?v=${key}"><div class="mini ${key}">${(key==='focus'?['4A']:key==='guided'?['1F','2A','4A']:['4A','4B']).map(id=>art(find(id),'')).join('')}</div><div><small>Direction ${v.n}</small><h2>${v.name}</h2><p>${v.desc}</p><small>${v.trade}</small><p><strong>Try this flow →</strong></p></div></a>`).join('')}</div><p class="notice"><a href="original.html">Open the original prototype</a> · Sample catalog only; no project data is saved.</p></div>`;}
function render(){app.innerHTML=`<div class="labbar"><a href="./?v=guided&favorites=first">← Prototype 2 · Frozen version</a><span>New exploration · Path list + pop-up picker</span><a href="./">All five original directions</a></div><main class="path-sheet"><header><div><span class="step-label">Effective length · Step 3 of 3</span><h1>Fittings in this path</h1><p class="muted">Build and review your path, one fitting at a time.</p></div><label>Preview path<select id="type"><option value="supply" ${type==='supply'?'selected':''}>Supply · Living room</option><option value="return" ${type==='return'?'selected':''}>Return · Hallway</option></select></label></header><section class="coverage" aria-label="Groups represented in this path"><small>Groups in this path</small><div id="group-coverage"></div></section><section class="path-table" aria-label="Fitting path entries"><div class="sheet-columns" aria-hidden="true"><span>#</span><span>Drawing</span><span>Fitting / group</span><span>EL each</span><span>Quantity</span><span>Subtotal</span><span></span></div><div id="rows"></div><button class="add-row" data-action="open-picker"><span aria-hidden="true">＋</span> Add fitting</button></section><div id="status" role="status"></div><footer class="sheet-total" id="totals" aria-live="polite"></footer><p class="notice">Prototype · Sample fitting catalog · Favorites saved in this browser; path entries are temporary.</p></main>`;
 picker.innerHTML=`<div class="picker-top"><div><small>Add a fitting to the ${type} path</small><h2 id="picker-title">Choose a fitting</h2></div><button data-action="close-picker" aria-label="Close fitting picker">Close</button></div><div id="picker-status" role="status"></div><div id="browser"></div>`;renderBrowser();renderRows();}
function renderBrowser(){const list=items(),target=document.getElementById('browser');let html='';if(variant==='guided'){
 html=`<div class="toolbar"><div class="actions"><button data-action="groups" ${stage==='groups'?'class="group-chip"':''}>1 · Choose group</button><button data-action="drawings" ${stage==='drawings'?'class="group-chip"':''}>2 · Choose fitting</button></div></div>`;
 if(stage==='groups')html+=`<div class="group-grid">${allowed[type].map(groupOverview).join('')}</div>`;
 else if(stage==='drawings')html+=`<div class="toolbar"><h2>${titles[group]}</h2><div class="actions">${favoriteFilters()}<button data-action="groups">Change group</button></div></div>${groupUsage(group)}${list.length?`<div class="grid">${list.map((f,i)=>groupDivider(list,i)+guidedCard(f)).join('')}</div>`:empty()}`;

 }else{
 html=`<div class="toolbar">${groupSelect()}<small>${list.length} ${favoriteLayout==='tabs'&&favoritesOnly?'favorite':'sample'} fittings${variant==='compare'?' · Select up to two to compare':''}</small>${variant==='compare'&&compareOpen?'':favoriteFilters()}</div>`;
 html+=groupUsage(group);
 if(!list.length&&!(variant==='compare'&&compareOpen))html+=empty();else if(variant==='gallery')html+=`<div class="grid">${list.map((f,i)=>groupDivider(list,i)+card(f)).join('')}</div>`;
 else if(variant==='focus'){if(!list.some(f=>f.id===selected))selected=list[0].id;const i=list.findIndex(f=>f.id===selected);html+=`<div class="focus-view"><div class="toolbar focus-heading"><small>Drawing ${i+1} of ${list.length}</small><div class="actions"><button data-action="previous" ${i===0?'disabled':''}>← Previous</button><button data-action="next" ${i===list.length-1?'disabled':''}>Next →</button></div></div>${config(find(selected))}<div class="filmstrip" aria-label="Fitting drawings">${list.map((f,i)=>`${groupDivider(list,i)}<button data-action="choose" data-id="${f.id}" aria-pressed="${selected===f.id}">${art(f,'')}<span>${favorites.has(f.id)?'★ ':''}${f.id}</span></button>`).join('')}</div></div>`;}
 else if(variant==='compare'){html+=compareOpen?`<div class="toolbar"><h2>Compare fittings</h2><button data-action="back-compare">← Change comparison</button></div><div class="compare-grid">${compare.map(id=>config(find(id))).join('')}</div>`:`<div class="grid">${list.map((f,i)=>groupDivider(list,i)+card(f,'toggle')).join('')}</div><div class="sticky-compare toolbar"><span>${compare.length?compare.join(' + '):'Select two fittings to inspect side by side'}</span><button class="primary" data-action="compare" ${compare.length!==2?'disabled':''}>Compare selected drawings</button></div>`;}
 else html+=`<div class="catalog">${list.map((f,i)=>`${groupDivider(list,i)}<article class="catalog-row"><div class="catalog-summary">${art(f,'')}<div><div class="favorite-heading"><span class="code">${f.id}</span>${favoriteButton(f.id)}</div><h2>${esc(f.name)}</h2><small>${f.fixed!==undefined?f.fixed+' ft per fitting':f.ratios?'Enter height and width':'Choose downstream branches'}</small></div><button data-action="expand" data-id="${f.id}" aria-expanded="${expanded===f.id}">${expanded===f.id?'Close details':'Configure fitting'}</button></div>${expanded===f.id?config(f):''}</article>`).join('')}</div>`;
 }target.innerHTML=html;refreshConfigs();}
function empty(){if(favoriteLayout==='tabs'&&favoritesOnly&&data.some(f=>f.group===group))return '<div class="empty"><h3>No favorites in this group yet</h3><p>Star the fittings you use most, then find them here.</p><button data-action="show-all">Browse all fittings</button></div>';return '<div class="empty">This group is available for the path, but has no sample drawings in this prototype.</div>';}
function refreshConfigs(){document.querySelectorAll('[data-config]').forEach(el=>{const id=el.dataset.config,d=draft(id),c=calculate(find(id),d),quantity=el.classList.contains('guided-input-card')?1:Number(d.quantity),ok=c.value!==null&&Number.isSafeInteger(quantity)&&quantity>0;el.querySelector('output').textContent=c.value===null?'—':c.value+' ft';el.querySelector('.reason').textContent=c.note;el.querySelector('.subtotal').textContent=ok?`${c.value} ft × ${quantity} = ${fmt(c.value*quantity)} ft for this entry`:'';const warning=repetitionWarning(id,quantity),warningBox=el.querySelector('.repetition-warning');warningBox.hidden=!warning;warningBox.textContent=warning;const addButton=el.querySelector('[data-action="add"]');addButton.disabled=!ok;addButton.textContent=editing>=0?(warning?'Save anyway':'Save fitting'):(warning?'Add anyway':'Add to path');});}
function renderRows(){const list=paths[type];document.getElementById('rows').innerHTML=list.length?list.map((r,i)=>`<article class="path-row sheet-row" data-row="${i}" aria-label="Row ${i+1}, fitting ${r.id}"><span class="row-number">${i+1}</span>${art(find(r.id),'sheet-art')}<div class="sheet-description"><span class="code">${r.id}</span><h3>${esc(find(r.id).name)}</h3><div class="sheet-group">Group ${find(r.id).group} · ${titles[find(r.id).group]}</div><small>${esc(r.note)}</small></div><div class="sheet-unit">${r.value}<small>ft each</small></div><label class="row-quantity-label"><span class="visually-hidden">Quantity for ${r.id}</span><input data-row-quantity="${i}" aria-label="Quantity for ${r.id}" type="number" min="1" step="1" value="${r.quantity}" aria-describedby="quantity-error-${i}"><small id="quantity-error-${i}" class="quantity-error" hidden></small></label><div class="sheet-subtotal" data-row-subtotal>${fmt(r.value*r.quantity)} ft<small>${r.value} ft × ${r.quantity}</small></div><div class="actions sheet-actions"><button data-action="edit" data-index="${i}">Edit</button><button data-action="remove" data-index="${i}" aria-label="Remove row ${i+1}, fitting ${r.id}">Remove</button></div><div class="row-usage-warning repetition-warning" role="status" hidden></div></article>`).join(''):'<div class="sheet-empty"><h2>Your fitting path starts here</h2><p>Use Add fitting to choose a group and a drawing.</p></div>';document.querySelector('.sheet-columns').hidden=!list.length;refreshRowWarnings();renderTotals();renderCoverage();}
function renderCoverage(){const groups=[...new Set(paths[type].map(r=>find(r.id).group))];document.getElementById('group-coverage').innerHTML=groups.length?groups.map(g=>`<span class="coverage-chip ${usuallyOnce.has(g)&&groupQuantity(g)>1?'coverage-warning':''}">Group ${g}<small>${groupQuantity(g)} fitting${groupQuantity(g)===1?'':'s'}</small></span>`).join(''):'<span class="muted">None added yet</span>';}
function renderTotals(){const total=paths[type].reduce((s,r)=>s+r.value*r.quantity,0),quantity=paths[type].reduce((s,r)=>s+r.quantity,0);document.getElementById('totals').innerHTML=`<div class="fitting-total"><small>Fitting equivalent length</small><strong>${fmt(total)} <span>ft</span></strong><small>${paths[type].length} rows · ${quantity} fitting${quantity===1?'':'s'}</small></div><div class="total-context"><div><small>Straight lengths from step 2</small><span>${straight[type]} ft</span></div><div><small>Total path equivalent length</small><strong>${fmt(total+straight[type])} ft</strong></div></div>`;}
function refreshRowWarnings(){document.querySelectorAll('#rows [data-row]').forEach(row=>{const entry=paths[type][Number(row.dataset.row)],box=row.querySelector('.row-usage-warning');if(!box)return;const g=find(entry.id).group,total=groupQuantity(g);box.hidden=!usuallyOnce.has(g)||total<=1;box.textContent=box.hidden?'':`Group ${g} is generally used once per path. This path contains ${total} fittings from this group.`;});}
function updateRowQuantity(input){const index=Number(input.dataset.rowQuantity),entry=paths[type][index];if(!entry)return;const value=Number(input.value),valid=Number.isSafeInteger(value)&&value>=1&&input.validity.valid;const row=input.closest('[data-row]'),error=row.querySelector('.quantity-error');input.setAttribute('aria-invalid',String(!valid));error.hidden=valid;if(!valid){error.textContent=`Enter a whole number of 1 or more. Totals still use ${entry.quantity}.`;return;}entry.quantity=value;entry.inputs.quantity=String(value);row.querySelector('[data-row-subtotal]').innerHTML=`${fmt(entry.value*value)} ft<small>${entry.value} ft × ${value}</small>`;renderBrowser();refreshRowWarnings();renderTotals();renderCoverage();const g=find(entry.id).group;status(`${entry.id} quantity updated to ${value}.${usuallyOnce.has(g)&&groupQuantity(g)>1?` Group ${g} is generally used once per path.`:''}`);}
function status(message){document.getElementById('status').textContent=message;document.getElementById('picker-status').textContent=message;}
function openConfig(id){if(picker.open)picker.close();selected=id;dialog.innerHTML=`<div class="actions"><small>${editing>=0?'Edit fitting':'Configure fitting'}</small><button data-action="close">Close</button></div><div class="favorite-status" role="status"></div>${config(find(id))}`;refreshConfigs();dialog.showModal();}
function choose(id){selected=id;editing=-1;if(variant==='guided'){draft(id).quantity='1';if(find(id).fixed!==undefined)commitEntry(id);return;}if(variant==='gallery')openConfig(id);else renderBrowser();}
function commitEntry(id){if(variant==='guided'&&editing<0)draft(id).quantity='1';const d=draft(id),c=calculate(find(id),d),quantity=Number(d.quantity);if(c.value===null||!Number.isSafeInteger(quantity)||quantity<1)return;const entry={id,inputs:{...d},value:c.value,quantity,note:c.note},wasEditing=editing>=0;if(wasEditing)paths[type][editing]=entry;else paths[type].push(entry);editing=-1;if(dialog.open)dialog.close();if(picker.open)picker.close();if(variant==='guided')stage='groups';renderBrowser();renderRows();status(`${id} ${wasEditing?'updated':'added'} · ${fmt(c.value*quantity)} ft`);}
function resetBrowse(){editing=-1;compare=[];compareOpen=false;expanded=null;selected=items()[0]?.id;stage='groups';}
function change(e){if(e.target.dataset.rowQuantity!==undefined){updateRowQuantity(e.target);return;}if(e.target.id==='favorite-layout'){favoriteLayout=e.target.value;favoritesOnly=false;const url=new URL(location.href);url.searchParams.set('favorites',favoriteLayout);history.replaceState(null,'',url);renderBrowser();return}if(e.target.id==='variation'){location.href='?v='+e.target.value+'&favorites='+favoriteLayout;return}if(e.target.id==='type'){type=e.target.value;group=type==='supply'?4:7;resetBrowse();render();return}if(e.target.id==='group'){group=Number(e.target.value);resetBrowse();renderBrowser();return}if(e.target.dataset.field){const parent=e.target.closest('[data-config]');draft(parent.dataset.config)[e.target.dataset.field]=e.target.value;refreshConfigs();}}
document.addEventListener('input',e=>{if(e.target.dataset.field||e.target.dataset.rowQuantity!==undefined)change(e)});document.addEventListener('change',change);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;
 if(action==='open-picker'){editing=-1;stage='groups';favoritesOnly=false;renderBrowser();document.getElementById('picker-status').textContent='';picker.showModal();picker.scrollTop=0;return;}
 if(action==='close-picker'){picker.close();editing=-1;return;}
 if(action==='favorite'){toggleFavorite(id);return}
 if(action==='show-all'||action==='show-favorites'){favoritesOnly=action==='show-favorites';renderBrowser();return}
 if(action==='group-favorites'){group=Number(b.dataset.group);favoritesOnly=favoriteLayout==='tabs';selected=items()[0]?.id;stage='drawings';editing=-1;renderBrowser();picker.scrollTop=0;return}
 if(action==='close'){dialog.close();editing=-1;return}
 if(action==='choose'){choose(id);return}
 if(action==='group-card'){favoritesOnly=false;group=Number(b.dataset.group);selected=items()[0]?.id;stage='drawings';editing=-1;renderBrowser();picker.scrollTop=0;return}
 if(action==='groups'||action==='drawings'){stage=action;editing=-1;renderBrowser();picker.scrollTop=0;return}
 if(action==='previous'||action==='next'){const list=items(),i=list.findIndex(f=>f.id===selected);selected=list[i+(action==='next'?1:-1)].id;editing=-1;renderBrowser();return}
 if(action==='expand'){expanded=expanded===id?null:id;selected=id;editing=-1;renderBrowser();return}
 if(action==='toggle'){if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length<2)compare.push(id);else{status('Two fittings are already selected. Deselect one to choose another.');return}renderBrowser();return}
 if(action==='compare'){compareOpen=true;editing=-1;renderBrowser();return}
 if(action==='back-compare'){compareOpen=false;editing=-1;renderBrowser();return}
 if(action==='edit'){const i=Number(b.dataset.index),r=paths[type][i];editing=i;selected=r.id;group=find(r.id).group;drafts[r.id]={...r.inputs};openConfig(r.id);return}
 if(action==='cancel-edit'){editing=-1;if(dialog.open)dialog.close();renderBrowser();return}
 if(action==='remove'){paths[type].splice(Number(b.dataset.index),1);editing=-1;renderBrowser();renderRows();status('Fitting removed.');return}
 if(action==='add'){commitEntry(id);return}
});
window.addEventListener('storage',e=>{if(e.key!==favoriteKey&&e.key!==null)return;favorites=readFavorites();if(variants[variant]){renderBrowser();syncFavoriteButtons();}});
picker.addEventListener('cancel',()=>{editing=-1});
dialog.addEventListener('cancel',()=>{editing=-1});render();
})();
